/** @generated by packages/shared/scripts/sync-flags.mjs — do not edit */
type FlagModule = string | { src?: string; default?: string | { src?: string } }

function resolveFlagModule(mod: FlagModule): string {
  if (typeof mod === 'string') return mod
  if (mod && typeof mod === 'object') {
    const d = mod.default
    if (typeof d === 'string') return d
    if (d && typeof d === 'object' && typeof d.src === 'string') return d.src
    if (typeof mod.src === 'string') return mod.src
  }
  return ''
}

