/** Webpack/Next bundled flag URL (no /public round-trip). */
export function getFlagBundledSrc(iso: string): string | undefined {
  const mod = FLAG_MODULES[iso]
  if (!mod) return undefined
  const src = resolveFlagModule(mod)
  return src || undefined
}
